<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserEmailVerifiedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserEmailVerifiedAccessor trait.
 *
 * Covers null default, string/VO assignment via withEmailVerified,
 * getEmailVerified/emailVerified accessors, and isEmailVerifiedChanged with/without original.
 */
class UserEmailVerifiedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withEmailVerified creates a new instance with the EmailVerified set
     * from a string value, and getEmailVerified returns the primitive string.
     */
    public function testWithEmailVerifiedFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailVerifiedAccessorUnitTest();

        // Act
        $result = $holder->withEmailVerified(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isEmailVerified());
    }
    /**
     * Asserts that withemailVerified has access to the value object
     * from a string value, and getEmailVerified returns the primitive string.
     */
    public function testWithEmailVerifiedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailVerifiedAccessorUnitTest();

        // Act
        $result = $holder->withEmailVerified(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->emailVerified()->value());
    }
    public function testChangedEmailVerified(): void
    {
        // Arrange
        $holder = new ImplWithUserEmailVerifiedAccessorUnitTest();
        $original = $holder->withEmailVerified(true);
        $same = $holder->withEmailVerified(true);
        $modified = $holder->withEmailVerified(false);

        // Act
        $unchanged = $holder->isEmailVerifiedChanged();
        $withSame = $original->isEmailVerifiedChanged($same);
        $withDiferent = $original->isEmailVerifiedChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserEmailVerifiedAccessorUnitTest
{
    use UserEmailVerifiedAccessor;
}
